import * as zod from "zod";
import { ApprovalMode } from "./approvalMode.zod.js";
import { ReasoningEffort } from "./reasoningEffort.zod.js";
import { TurnStatus } from "./turnStatus.zod.js";
import { TurnType } from "./turnType.zod.js";
import { Usage } from "./usage.zod.js";

export const threadTurnResourceToolCallsMin = 0;

export const ThreadTurnResource = zod
  .strictObject({
    id: zod.string(),
    threadId: zod.string(),
    type: TurnType,
    status: TurnStatus,
    firstOrdinal: zod
      .int()
      .nullable()
      .describe("The first item the turn wrote. Null before it has written one."),
    lastOrdinal: zod.int().nullable().describe("The last item the turn wrote so far."),
    preview: zod
      .string()
      .nullable()
      .describe(
        "The beginning of the message that started the turn. Null for compaction turns and turns started by the assistant itself.",
      ),
    modelId: zod.string(),
    reasoningEffort: zod.union([ReasoningEffort, zod.null()]),
    approvalMode: ApprovalMode,
    failureCode: zod
      .string()
      .nullable()
      .describe("Why the turn failed. Null unless status is failed."),
    toolCalls: zod
      .int()
      .min(threadTurnResourceToolCallsMin)
      .describe("How many tools the turn called."),
    usage: Usage.describe(
      "Tokens used by every model request of this turn, including title generation, review and compaction.",
    ),
    startedAt: zod.iso.datetime({ offset: true }),
    firstTokenAt: zod.iso
      .datetime({ offset: true })
      .nullable()
      .describe("When the first output token arrived. Null until then."),
    completedAt: zod.iso
      .datetime({ offset: true })
      .nullable()
      .describe("Null while the turn is running."),
  })
  .describe("One run of the agent, from the message that started it until it stopped.");

export type ThreadTurnResource = zod.input<typeof ThreadTurnResource>;
export type ThreadTurnResourceOutput = zod.output<typeof ThreadTurnResource>;
